UPDATE WORKSPACES
SET 
    WS_NAME = #{wsName},
    WS_DESCRIPTION = #{wsDescription}
    
    , WS_IMAGE_PATH = #{wsImagePath}
    
WHERE WS_ID = #{wsId}

UPDATE WS_MEMBERS 
SET WS_ROLE = #{role}
WHERE WS_ID = #{wsId} AND USER_ID = #{userId}

UPDATE WORKSPACES 
SET OWNER_ID = #{ownerId} 
WHERE WS_ID = #{wsId}

